print(issue_credit_note(Invoice("i","c",lines=[LineItem("x",1,Decimal("1000"))],status="issued"), Decimal("600"), "x", approved_by="mgr"))
# idempotency
i=inv(); a=issue_credit_note(i, Decimal("10"), "g", idempotency_key="k1")
b=issue_credit_note(i, Decimal("10"), "g", idempotency_key="k1")
